from fastapi import FastAPI, HTTPException
import sqlite3

app = FastAPI()
db = sqlite3.connect('app.db')

@app.get('/users/{user_id}')
def get_user(user_id):
    cursor = db.execute(f'SELECT * FROM users WHERE id = {user_id}')
    user = cursor.fetchone()
    if not user:
        raise HTTPException(status_code=404)
    return {'user': user}

@app.post('/users')
def create_user(name, email, password):
    db.execute(f"INSERT INTO users (name, email, password) VALUES ('{name}', '{email}', '{password}')")
    db.commit()
    return {'status': 'ok'}

@app.get('/users')
def list_users(limit=1000):
    cursor = db.execute(f'SELECT * FROM users LIMIT {limit}')
    return {'users': cursor.fetchall()}
